using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;
using Entitas.SourceGenerator.CodeGeneration;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Entitas.SourceGenerator
{
    /// <summary>
    /// Everything both halves of <c>Output = GenerationOutput.Files</c> must agree on: what a
    /// generated file looks like, how one is recognised, and where they go.
    ///
    /// The writer (entitas-gen, driven by the Unity editor or a terminal) lives outside this
    /// assembly because analyzers may not do IO; the compiler side — discovery skipping its
    /// own output, the source generator standing down and reporting stale files — lives here.
    /// Keeping the format in one place is what guarantees a written file is exactly what the
    /// source generator would have emitted, plus one marker line.
    /// </summary>
    public static class GeneratedFiles
    {
        /// <summary>First line of every generated source, in both modes.</summary>
        public const string AutoGeneratedLine = "// <auto-generated/>";

        /// <summary>
        /// Second line of a generated FILE. It is what makes a file ours: only files starting
        /// with these two lines are ever skipped by discovery, overwritten or deleted.
        /// </summary>
        public const string MarkerLine =
            "// Generated by Entitas-Flux. Do not edit: regenerate with Tools > Entitas > Generate in Unity, or entitas-gen.";

        const string MarkerPrefix = "// Generated by Entitas-Flux.";

        /// <summary>Header the pre-file-mode entitas-gen wrote; recognised so its leftovers can be cleaned up.</summary>
        const string LegacyHeaderPrefix =
            "//------------------------------------------------------------------------------\n" +
            "// <auto-generated>\n" +
            "//     This code was generated by the Entitas source generator.";

        /// <summary>Default folder name, created next to the file declaring the contexts.</summary>
        public const string DefaultFolderName = "Generated";

        /// <summary>The text the source generator adds as a compilation unit.</summary>
        public static string SourceGeneratorText(GeneratedSource source) =>
            AutoGeneratedLine + "\n" + source.Content;

        /// <summary>The text written to disk: the source generator's text plus the marker line.</summary>
        public static string FileText(GeneratedSource source) =>
            AutoGeneratedLine + "\n" + MarkerLine + "\n" + NormalizeNewlines(source.Content);

        /// <summary>Inverse of the marker insertion; used to prove both modes emit the same code.</summary>
        public static string WithoutMarker(string fileText)
        {
            var text = NormalizeNewlines(fileText);
            var prefix = AutoGeneratedLine + "\n" + MarkerLine + "\n";
            return text.StartsWith(prefix, StringComparison.Ordinal)
                ? AutoGeneratedLine + "\n" + text.Substring(prefix.Length)
                : text;
        }

        public static string NormalizeNewlines(string text) =>
            text.IndexOf('\r') < 0 ? text : text.Replace("\r\n", "\n").Replace('\r', '\n');

        // -- recognition ----------------------------------------------------------

        /// <summary>
        /// True for a file Entitas-Flux wrote. Deliberately strict — the marker must be the
        /// second line, right after <c>// &lt;auto-generated/&gt;</c> — because a positive
        /// answer licenses deleting the file.
        /// </summary>
        public static bool IsGenerated(string text)
        {
            if (text.StartsWith(AutoGeneratedLine, StringComparison.Ordinal))
            {
                var index = AutoGeneratedLine.Length;
                if (index < text.Length && text[index] == '\r')
                    index++;
                if (index < text.Length && text[index] == '\n')
                    return string.CompareOrdinal(text, index + 1, MarkerPrefix, 0, MarkerPrefix.Length) == 0;

                return false;
            }

            return text.StartsWith("//---", StringComparison.Ordinal) &&
                   NormalizeNewlines(text.Substring(0, Math.Min(text.Length, LegacyHeaderPrefix.Length + 8)))
                       .StartsWith(LegacyHeaderPrefix, StringComparison.Ordinal);
        }

        static readonly ConditionalWeakTable<SyntaxTree, StrongBox<bool>> IsGeneratedCache =
            new ConditionalWeakTable<SyntaxTree, StrongBox<bool>>();

        /// <summary>
        /// Cached per tree instance: Roslyn reuses the trees of unchanged files across
        /// compilations, so on a keystroke only the edited file is looked at again.
        /// </summary>
        public static bool IsGenerated(SyntaxTree tree) =>
            IsGeneratedCache.GetValue(tree, static t =>
            {
                var text = t.GetText();
                var head = text.ToString(new TextSpan(0, Math.Min(text.Length, 256)));
                return new StrongBox<bool>(IsGenerated(head));
            }).Value;

        /// <summary>The trees of a compilation that Entitas-Flux wrote. Empty in source generator mode.</summary>
        public static IReadOnlyList<SyntaxTree> FindGeneratedTrees(Compilation compilation)
        {
            List<SyntaxTree>? found = null;
            foreach (var tree in compilation.SyntaxTrees)
            {
                if (IsGenerated(tree))
                    (found ??= new List<SyntaxTree>()).Add(tree);
            }

            return (IReadOnlyList<SyntaxTree>?)found ?? Array.Empty<SyntaxTree>();
        }

        // -- location ---------------------------------------------------------------

        /// <summary>
        /// The configured output folder: <c>OutputPath</c> under <paramref name="projectRoot"/>,
        /// or <c>Generated</c> next to the file that declares the first context. Returned with
        /// forward slashes, in the same form (absolute or relative) as the inputs.
        /// </summary>
        public static string? OutputDirectory(Compilation compilation, EntitasGenerationOptions options, string? projectRoot)
        {
            if (!string.IsNullOrWhiteSpace(options.OutputPath))
            {
                var relative = NormalizePath(options.OutputPath).Trim('/');
                return string.IsNullOrEmpty(projectRoot)
                    ? relative
                    : NormalizePath(projectRoot!).TrimEnd('/') + "/" + relative;
            }

            var declaration = ContextDeclarationFile(compilation);
            if (declaration == null)
                return null;

            var slash = declaration.LastIndexOf('/');
            var directory = slash < 0 ? string.Empty : declaration.Substring(0, slash);
            return directory.Length == 0 ? DefaultFolderName : directory + "/" + DefaultFolderName;
        }

        /// <summary>Path of the file holding the first <c>[assembly: ContextDefinition]</c>.</summary>
        public static string? ContextDeclarationFile(Compilation compilation)
        {
            foreach (var attribute in compilation.Assembly.GetAttributes())
            {
                if (attribute.AttributeClass?.ToCompilableString() != AttributeNames.ContextDefinition)
                    continue;

                var path = attribute.ApplicationSyntaxReference?.SyntaxTree.FilePath;
                return string.IsNullOrEmpty(path) ? null : NormalizePath(path!);
            }

            return null;
        }

        /// <summary>
        /// The logical file name (e.g. <c>Game/Components/GameHealthComponent.cs</c>) of a
        /// generated file at <paramref name="path"/>, or null when it is not inside
        /// <paramref name="outputDirectory"/> — an orphan, e.g. after OutputPath changed.
        /// A relative output directory (as configured, "Assets/…") matches as a path
        /// segment, so it works for absolute IDE paths and relative Unity paths alike.
        /// </summary>
        public static string? LogicalName(string path, string outputDirectory)
        {
            var file = NormalizePath(path);
            var directory = NormalizePath(outputDirectory).TrimEnd('/') + "/";

            if (file.StartsWith(directory, StringComparison.Ordinal))
                return file.Substring(directory.Length);

            if (!directory.StartsWith("/", StringComparison.Ordinal) && !(directory.Length > 1 && directory[1] == ':'))
            {
                var segment = "/" + directory;
                var index = file.IndexOf(segment, StringComparison.Ordinal);
                if (index >= 0)
                    return file.Substring(index + segment.Length);
            }

            return null;
        }

        public static string NormalizePath(string path) => path.Replace('\\', '/');

        // -- staleness --------------------------------------------------------------

        /// <summary>
        /// Compares what generation produces now with the generated files present — on disk
        /// for the writer, in the compilation for the source generator — by content, ignoring
        /// line endings (a git checkout on Windows must not count as a change).
        /// </summary>
        public static Staleness Compare(IReadOnlyList<GeneratedSource> expected, IReadOnlyList<ExistingGeneratedFile> existing)
        {
            var byName = new Dictionary<string, ExistingGeneratedFile>(StringComparer.Ordinal);
            var orphans = new List<string>();
            foreach (var file in existing)
            {
                if (file.LogicalName == null || byName.ContainsKey(file.LogicalName))
                    orphans.Add(file.Path);
                else
                    byName.Add(file.LogicalName, file);
            }

            var missing = new List<string>();
            var changed = new List<string>();
            var expectedNames = new HashSet<string>(StringComparer.Ordinal);
            foreach (var source in expected)
            {
                expectedNames.Add(source.FileName);
                if (!byName.TryGetValue(source.FileName, out var file))
                    missing.Add(source.FileName);
                else if (file.ContentHash != Hash(FileText(source)))
                    changed.Add(source.FileName);
            }

            foreach (var file in byName.Values)
            {
                if (!expectedNames.Contains(file.LogicalName!))
                    orphans.Add(file.Path);
            }

            orphans.Sort(StringComparer.Ordinal);
            return new Staleness(missing, changed, orphans);
        }

        /// <summary>FNV-1a over the newline-normalized text: stable across processes and platforms.</summary>
        public static ulong Hash(string text)
        {
            const ulong offset = 14695981039346656037UL;
            const ulong prime = 1099511628211UL;

            var hash = offset;
            for (var i = 0; i < text.Length; i++)
            {
                var c = text[i];
                if (c == '\r')
                {
                    if (i + 1 < text.Length && text[i + 1] == '\n')
                        continue;
                    c = '\n';
                }

                hash ^= c;
                hash *= prime;
            }

            return hash;
        }
    }

    /// <summary>A generated file that already exists: where it is, what it holds.</summary>
    public sealed class ExistingGeneratedFile : IEquatable<ExistingGeneratedFile>
    {
        public string Path { get; }

        /// <summary>Path relative to the output folder; null when the file is outside it.</summary>
        public string? LogicalName { get; }

        public ulong ContentHash { get; }

        public ExistingGeneratedFile(string path, string? logicalName, ulong contentHash)
        {
            Path = path;
            LogicalName = logicalName;
            ContentHash = contentHash;
        }

        public bool Equals(ExistingGeneratedFile? other) =>
            other != null &&
            string.Equals(Path, other.Path, StringComparison.Ordinal) &&
            string.Equals(LogicalName, other.LogicalName, StringComparison.Ordinal) &&
            ContentHash == other.ContentHash;

        public override bool Equals(object? obj) => Equals(obj as ExistingGeneratedFile);

        public override int GetHashCode() => unchecked(StringComparer.Ordinal.GetHashCode(Path) * 397 ^ ContentHash.GetHashCode());
    }

    /// <summary>The difference between what would be generated and what is there.</summary>
    public sealed class Staleness
    {
        /// <summary>Logical names that should exist and do not.</summary>
        public IReadOnlyList<string> Missing { get; }

        /// <summary>Logical names whose content differs.</summary>
        public IReadOnlyList<string> Changed { get; }

        /// <summary>Paths of generated files that are no longer generated (or are outside the output folder).</summary>
        public IReadOnlyList<string> Orphans { get; }

        public bool IsUpToDate => Missing.Count == 0 && Changed.Count == 0 && Orphans.Count == 0;

        public Staleness(IReadOnlyList<string> missing, IReadOnlyList<string> changed, IReadOnlyList<string> orphans)
        {
            Missing = missing;
            Changed = changed;
            Orphans = orphans;
        }

        public string Describe(int examples = 3)
        {
            var parts = new List<string>();
            if (Missing.Count > 0)
                parts.Add($"{Missing.Count} missing ({Examples(Missing, examples)})");
            if (Changed.Count > 0)
                parts.Add($"{Changed.Count} outdated ({Examples(Changed, examples)})");
            if (Orphans.Count > 0)
                parts.Add($"{Orphans.Count} no longer generated ({Examples(Orphans, examples)})");

            return string.Join(", ", parts);
        }

        static string Examples(IReadOnlyList<string> items, int count)
        {
            var sb = new StringBuilder();
            for (var i = 0; i < items.Count && i < count; i++)
            {
                if (i > 0)
                    sb.Append(", ");
                sb.Append(items[i]);
            }

            if (items.Count > count)
                sb.Append(", …");

            return sb.ToString();
        }
    }

    /// <summary>
    /// The generated files a compilation already contains, as a value — so the source
    /// generator can re-check staleness only when one of them actually changed.
    /// </summary>
    public sealed class GeneratedFilesInCompilation : IEquatable<GeneratedFilesInCompilation>
    {
        public static readonly GeneratedFilesInCompilation None =
            new GeneratedFilesInCompilation(Array.Empty<ExistingGeneratedFile>());

        public IReadOnlyList<ExistingGeneratedFile> Files { get; }

        GeneratedFilesInCompilation(IReadOnlyList<ExistingGeneratedFile> files)
        {
            Files = files;
        }

        static readonly ConditionalWeakTable<SyntaxTree, StrongBox<ulong>> HashCache =
            new ConditionalWeakTable<SyntaxTree, StrongBox<ulong>>();

        public static GeneratedFilesInCompilation From(Compilation compilation)
        {
            var trees = GeneratedFiles.FindGeneratedTrees(compilation);
            if (trees.Count == 0)
                return None;

            var options = EntitasGenerators.ReadOptions(compilation);
            var outputDirectory = GeneratedFiles.OutputDirectory(compilation, options, null);

            var files = trees
                .Select(tree => new ExistingGeneratedFile(
                    GeneratedFiles.NormalizePath(tree.FilePath),
                    outputDirectory == null ? null : GeneratedFiles.LogicalName(tree.FilePath, outputDirectory),
                    HashCache.GetValue(tree, static t => new StrongBox<ulong>(GeneratedFiles.Hash(t.GetText().ToString()))).Value))
                .OrderBy(file => file.Path, StringComparer.Ordinal)
                .ToArray();

            return new GeneratedFilesInCompilation(files);
        }

        public bool Equals(GeneratedFilesInCompilation? other) =>
            other != null && Files.SequenceEqual(other.Files);

        public override bool Equals(object? obj) => Equals(obj as GeneratedFilesInCompilation);

        public override int GetHashCode()
        {
            var hash = Files.Count;
            foreach (var file in Files)
                hash = unchecked(hash * 31 + (int)file.ContentHash);
            return hash;
        }
    }
}
